import json
from pathlib import Path
from collections import Counter
root = Path("/workspace/observed_run/harbor_trials")
recs = [json.loads(l) for l in Path("/workspace/observed_run/experiment_logs/rollout_records.jsonl").read_text().splitlines() if l.strip()]
by_name = {Path(r["trial_dirs"][0]).name: r for r in recs}

def obs_kinds(steps):
    kinds=[]
    for i,s in enumerate(steps):
        if s.get("source")!="agent":
            continue
        obs=s.get("observation") or {}
        results=obs.get("results") or []
        texts=[]
        for res in results:
            c=res.get("content") or ""
            if "No tool calls found" in c:
                texts.append("no_tool")
            elif "output token limit" in c or "reached the output token limit" in c:
                texts.append("length_limit")
            elif "Tool call error" in c:
                texts.append("tool_err")
            elif "Unknown tool" in c or "Error parsing" in c:
                texts.append("parse")
            else:
                texts.append("tool")
        # reasoning present?
        kinds.append((i, s.get("step_id"), texts, bool(s.get("tool_calls")), (s.get("message") or "")[:40].replace("\n"," ")))
    return kinds

# mismatches: leaves != fmt+1
print("OUTLIERS")
for d in sorted(root.iterdir()):
    if not d.is_dir(): continue
    data=json.loads((d/"agent"/"trajectory.json").read_text())
    steps=data["steps"]
    fmt=0
    for s in steps:
        for res in (s.get("observation") or {}).get("results") or []:
            c=res.get("content") or ""
            if "Tool call error" in c or "No tool calls" in c or "output token limit" in c:
                fmt+=1
    r=by_name[d.name]
    if r["leaf_count"]==fmt+1:
        continue
    print("="*70)
    print(d.name, "leaves", r["leaf_count"], "fmt", fmt, "delta", r["leaf_count"]-(fmt+1), "status", r["statuses"], "exit", r["exit_statuses"])
    kinds=obs_kinds(steps)
    # print only non-tool or last few
    for item in kinds:
        if item[2]!=["tool"] and item[2]!=[]:
            print(" ", item)
    print("  n agent", len(kinds), "last3", kinds[-3:])
    # count consecutive format errors
    # look at message roles sequence from ATIF more carefully
    sources=Counter(s.get("source") for s in steps)
    print("  sources", sources)
